package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.genetics.SpliceAiVcf;
import org.jlinalg.genetics.VepVcf;
import org.jlinalg.sequence.FastaIndexes;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

/** Portable literal SpliceAI ledgers and a complete source-bound original five-model workflow. */
public final class SpliceAiToolsCli {
    private SpliceAiToolsCli(){ }
    static final String ACTION="Use the explicit annotation edition, assembly, full FASTA/index and requested distance/mask. Original1.3 CPU inference requires its qualified private Linux x86_64 Python/dependency tree and all five unchanged models. If unavailable or installation is forbidden, retain SKIP3 and skip dependent analysis. Restore missing prerequisites; investigate FAIL2 and preserved original logs before retrying into a new output directory. Never replace model editions, reduce windows/models/input alleles, repair REF/IDs or convert missing/nonfinite scores to zero. Native mode audits supplied annotations and does not execute prediction. Observed DS maxima/minima are descriptive; no clinical or paper-specific masks are applied. Source scores have two-decimal quantization: 0.00 is not proof of biological absence. Bundled annotations are GENCODE24lift37 or GENCODE24, not GENCODE39/BRaVa. Source chromosome-prefix lookup is recorded without changing variant labels. Saved verification checks integrity and recomputes all native ledgers; it does not repeat neural inference or independently authenticate external resources. Capacities are monitored bounds, not OS quotas. Inputs are not submitted to a public API.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){Path root=null;boolean owned=false;
        try{
            if(args.length==1&&args[0].equals("--help")){out.println("spliceai-tools --request JSON | --verify BUNDLE\nBackends NATIVE and ORIGINAL. See docs/spliceai-tools.md.\n"+ACTION);return 0;}
            if(args.length==2&&args[0].equals("--verify")){verify(Path.of(args[1]));out.println("Verified saved SpliceAI capture and recomputed all native ledgers. "+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request JSON, --verify BUNDLE or --help");Path source=Path.of(args[1]).toAbsolutePath().normalize();byte[] bytes=NextflowFiles.bytes(source,2000000);var raw=object(SimpleJson.parse(NextflowFiles.utf8(bytes)),"request");root=resolve(source.getParent(),text(raw,"out"));Files.createDirectories(root.getParent());Files.createDirectory(root);owned=true;Files.write(root.resolve("source-request.json"),bytes,StandardOpenOption.CREATE_NEW);for(String name:List.of("inputs","source","worker","results"))Files.createDirectory(root.resolve(name));json(root.resolve("analysis-status.json"),Map.of("status","RUNNING","results_admitted",false));var r=SpliceAiToolsRequest.validate(raw);boolean original=text(r,"backend").equals("ORIGINAL");json(root.resolve("source-bindings.json"),sources());SpliceAiToolsRuntime.sources(root,r,false);SpliceAiToolsRuntime.Prepared runtime=original?SpliceAiToolsRuntime.prepare(root,source.getParent(),r):null;var inputs=SpliceAiToolsInputs.prepare(root,source.getParent(),raw,r,runtime);json(root.resolve("request.json"),inputs.captured());var effective=SpliceAiToolsRequest.validate(inputs.captured());json(root.resolve("effective-request.json"),effective);
            Map<String,Object> summary=original?SpliceAiToolsWorkflow.run(root,effective,inputs,runtime):Map.of("native",SpliceAiToolsTables.render(inputs.original(),inputs.annotated(),root.resolve("results/native"),effective,false));inputs.verify();if(runtime!=null)runtime.verify();json(root.resolve("result-summary.json"),summary);Files.writeString(root.resolve("WARNINGS.md"),warning(summary,original),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);SpliceAiToolsRuntime.capacity(root,effective,false,new long[1]);json(root.resolve("analysis-status.json"),state(summary,original));SpliceAiToolsFiles.seal(root);verify(root);out.println("Completed scoped SpliceAI analysis: "+root);err.println("WARNINGS / REQUIRED ACTIONS: "+root.resolve("WARNINGS.md")+"\n"+ACTION);return 0;
        }catch(Exception|LinkageError|OutOfMemoryError failure){int code=failure instanceof SpliceAiToolsRuntime.Unavailable?3:2;String state=code==3?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT";err.println(state+": "+failure+(owned&&root!=null?"\nWARNINGS / REQUIRED ACTIONS: "+root.resolve("WARNINGS.md"):"")+"\n"+ACTION);if(failure instanceof InterruptedIOException||failure instanceof InterruptedException)Thread.currentThread().interrupt();if(owned&&root!=null)try{json(root.resolve("analysis-status.json"),Map.of("status",state,"results_admitted",false,"cause",failure.toString(),"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"# "+state+"\n\nCAUSE: "+failure+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8);try(var writer=new PrintWriter(Files.newBufferedWriter(root.resolve("failure-stack.txt"),StandardCharsets.UTF_8))){failure.printStackTrace(writer);}SpliceAiToolsFiles.seal(root);}catch(IOException e){err.println("Could not seal complete SpliceAI failure diagnostics: "+e+"; retain output directory");}return code;}
    }
    static Map<String,Object> state(Map<String,Object> summary,boolean original)throws IOException{boolean predicted=false;for(Object value:summary.values()){var report=object(value,"summary");predicted|=((Number)report.get("annotations")).longValue()>((Number)report.get("missing_score_annotations")).longValue();}return Map.of("status","COMPLETE_SCOPED_SPLICEAI_ANALYSIS","results_admitted",true,"original_five_model_engine_executed",original,"prediction_model_executed",original&&predicted,"whole_paper_reproduced",false);}
    static void verify(Path supplied)throws IOException{
        Path root=supplied.toAbsolutePath().normalize();var seal=read(root.resolve("capture-files.json"),268435456);keys(seal,Set.of("schema_version","authentication","files"));if(integer(seal,"schema_version",0,1,1)!=1||!Boolean.FALSE.equals(seal.get("authentication")))throw new IOException("Invalid SpliceAI integrity seal");var files=SpliceAiToolsFiles.hashes(root);files.remove("capture-files.json");if(!same(files,seal.get("files")))throw new IOException("Saved SpliceAI capture bytes/population changed");var captured=read(root.resolve("request.json"));var r=SpliceAiToolsRequest.validate(captured);boolean original=text(r,"backend").equals("ORIGINAL");if(!".".equals(captured.get("out"))||!same(r,read(root.resolve("effective-request.json")))||!same(sources(),read(root.resolve("source-bindings.json"))))throw new IOException("Saved SpliceAI options or producer changed");SpliceAiToolsRuntime.sources(root,r,true);var raw=read(root.resolve("source-request.json"));SpliceAiToolsRequest.validate(raw);var expected=new LinkedHashMap<String,Object>(raw);expected.put("out",".");
        var summary=new LinkedHashMap<String,Object>();
        if(original){expected.put("input_vcf","inputs/original.vcf");expected.put("runtime",captured.get("runtime"));var reference=new LinkedHashMap<String,Object>(object(raw.get("reference"),"reference"));var currentReference=object(captured.get("reference"),"reference");for(String key:List.of("fasta","fai"))reference.put(key,currentReference.get(key));expected.put("reference",reference);var a=object(raw.get("annotation"),"annotation");if("provided".equals(a.get("kind"))){a.put("file","inputs/annotation.tsv");expected.put("annotation",a);}if(!same(SpliceAiToolsInputs.validateAnnotation(root.resolve("inputs/annotation.tsv"),r),read(root.resolve("annotation-summary.json"))))throw new IOException("Saved complete gene annotation summary changed");for(Object value:list(r.get("analyses"),"analyses")){var analysis=object(value,"analysis");String id=text(analysis,"id");Path directory=root.resolve("worker/"+id);var worker=read(directory.resolve("worker-request.json"));for(String key:List.of("distance","mask"))if(!same(worker.get(key),analysis.get(key)))throw new IOException("Saved original neural analysis options differ");if(!same(worker.get("threads"),r.get("threads")))throw new IOException("Saved original CPU budget differs");var process=read(directory.resolve("process-receipt.json"));if(integer(process,"original_exit_code",-1,0,0)!=0)throw new IOException("Original worker did not exit successfully");var report=read(directory.resolve("runtime-report.json"),16777216);if(!Boolean.TRUE.equals(report.get("main_returned_normally"))||integer(report,"model_assets_required",0,5,5)!=5||!Boolean.FALSE.equals(report.get("tensorflow_gpu_available")))throw new IOException("Saved original engine did not return normally with the full model ensemble");var result=SpliceAiToolsTables.render(root.resolve("inputs/original.vcf"),directory.resolve("original.vcf"),root.resolve("results/"+id),r,true);SpliceAiToolsWorkflow.admit(result);summary.put(id,result);}}
        else{expected.put("annotated_vcf","inputs/annotated.vcf");Path input=null;if(raw.containsKey("original_vcf")){expected.put("original_vcf","inputs/original.vcf");input=root.resolve("inputs/original.vcf");}summary.put("native",SpliceAiToolsTables.render(input,root.resolve("inputs/annotated.vcf"),root.resolve("results/native"),r,true));}
        if(!same(expected,captured)||!same(summary,read(root.resolve("result-summary.json")))||!same(state(summary,original),read(root.resolve("analysis-status.json")))||!warning(summary,original).equals(Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8)))throw new IOException("Saved SpliceAI scientific options, native ledgers, summaries, state or warnings differ");Set<String> analyses=original?summary.keySet():Set.of("native");for(String name:List.of("results","worker")){var actual=new TreeSet<String>();try(var paths=Files.list(root.resolve(name))){for(Path p:paths.toList()){if(!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("Unexpected SpliceAI analysis member");actual.add(p.getFileName().toString());}}if(!actual.equals(name.equals("worker")&&!original?Set.of():analyses))throw new IOException("Complete SpliceAI analysis population differs");}SpliceAiToolsRuntime.capacity(root,r,false,new long[1]);
    }
    private static String warning(Map<String,Object> summary,boolean original)throws IOException{return "# WARNINGS AND REQUIRED ACTIONS\n\n"+ACTION+"\n\n"+(original?"Original five-model engine invoked. Every missing tuple or unannotated allele remains unassessable; inspect counts, raw VCF and worker stderr. Source deprecation, CPU-instruction and missing-training-configuration messages are preserved. The unchanged models perform inference without compilation.\n":"NATIVE IMPORT: no neural prediction executed; source annotation options and editions are not inferred. Missing or nonfinite values remain unassessable.\n")+"\nComplete analysis counts:\n\n```json\n"+NextflowJson.json(summary)+"\n```\n";}
    private static Map<String,Object> sources()throws IOException{var classes=List.<Class<?>>of(SpliceAiToolsCli.class,SpliceAiToolsRequest.class,SpliceAiToolsFiles.class,SpliceAiToolsInputs.class,SpliceAiToolsRuntime.class,SpliceAiToolsWorkflow.class,SpliceAiToolsTables.class,SpliceAiVcf.class,VepVcf.class,FastaIndexes.class,LofteeRuntimeTree.class,LofteeWorkflowRuntime.Group.class,NextflowFiles.class,NextflowJson.class,NextflowParameters.class,SeuratDifferentialContracts.class,SimpleJson.class,RsemJson.class,OwnedProcesses.class);var origins=new TreeMap<String,Object>();Set<Class<?>> seen=new HashSet<>();for(Class<?> type:classes)source(type,seen,origins);var paths=new TreeSet<Path>();for(Class<?> type:classes)try{Path p=Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();if(Files.isRegularFile(p))paths.add(p);}catch(java.net.URISyntaxException e){throw new IOException("Invalid SpliceAI producer container",e);}var containers=new TreeSet<String>();for(Path p:paths)containers.add(NextflowJson.json(SpliceAiToolsFiles.pin(p,1000000000L)));return Map.of("schema_version",1,"authentication",false,"classes",origins,"complete_jar_containers",List.copyOf(containers));}
    private static void source(Class<?> type,Set<Class<?>> seen,Map<String,Object> origins)throws IOException{if(!seen.add(type))return;String name=type.getName().replace('.','/')+".class";try(var stream=type.getResourceAsStream("/"+name)){if(stream==null)throw new IOException("SpliceAI producer class unavailable");byte[] bytes=stream.readAllBytes();origins.put(name,Map.of("bytes",bytes.length,"sha256",NextflowFiles.sha(bytes)));}for(Class<?> nested:type.getDeclaredClasses())source(nested,seen,origins);}
}
